using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Marina.Application.Abstractions; using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Marina.Domain.Security; using Marina.Infrastructure.Security; using Microsoft.Extensions.Configuration; using Microsoft.IdentityModel.Tokens; using Xunit;
namespace Marina.SecurityTests;
public sealed class TokenSecurityTests{private const string SigningKey="a-strong-test-signing-key-with-more-than-32-characters";[Fact]public async Task Refresh_token_is_random_and_only_hash_is_persisted(){var db=new FakeDb();var service=new JwtTokenService(Configuration(),db,new EmptyPermissions());var pair=await service.IssueAsync(Guid.NewGuid(),"user@example.com",["Customer"],"test","agent","127.0.0.1");var persisted=Assert.Single(db.Added.OfType<RefreshToken>());Assert.NotEqual(pair.RefreshToken,persisted.TokenHash);Assert.Equal(64,persisted.TokenHash.Length);Assert.True(Convert.FromBase64String(pair.RefreshToken).Length>=64);}[Fact]public async Task Weak_signing_key_is_rejected(){var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Jwt:Key","weak"},{"Jwt:Issuer","test"},{"Jwt:Audience","app"}}).Build();var service=new JwtTokenService(config,new FakeDb(),new EmptyPermissions());await Assert.ThrowsAsync<InvalidOperationException>(()=>service.IssueAsync(Guid.NewGuid(),"u@e.com",["Customer"],"d","a","i"));}
[Fact]public async Task Valid_access_token_passes_strict_validation(){var pair=await IssueAsync();var principal=new JwtSecurityTokenHandler().ValidateToken(pair.AccessToken,ValidationParameters(),out var validated);Assert.IsType<JwtSecurityToken>(validated);Assert.NotNull(principal.FindFirst(ClaimTypes.NameIdentifier));}
[Fact]public async Task Tampered_access_token_is_rejected(){var pair=await IssueAsync();var parts=pair.AccessToken.Split('.');var signature=parts[2].ToCharArray();signature[signature.Length/2]=signature[signature.Length/2]=='A'?'B':'A';var tampered=$"{parts[0]}.{parts[1]}.{new string(signature)}";Assert.ThrowsAny<SecurityTokenValidationException>(()=>new JwtSecurityTokenHandler().ValidateToken(tampered,ValidationParameters(),out _));}
[Fact]public async Task Access_token_with_wrong_issuer_is_rejected(){var pair=await IssueAsync();var parameters=ValidationParameters();parameters.ValidIssuer="another-issuer";Assert.Throws<SecurityTokenInvalidIssuerException>(()=>new JwtSecurityTokenHandler().ValidateToken(pair.AccessToken,parameters,out _));}
[Fact]public async Task Access_token_with_wrong_audience_is_rejected(){var pair=await IssueAsync();var parameters=ValidationParameters();parameters.ValidAudience="another-audience";Assert.Throws<SecurityTokenInvalidAudienceException>(()=>new JwtSecurityTokenHandler().ValidateToken(pair.AccessToken,parameters,out _));}
[Fact]public void Expired_access_token_is_rejected(){var now=DateTime.UtcNow;var token=new JwtSecurityToken("test","test-app",[new Claim(ClaimTypes.NameIdentifier,Guid.NewGuid().ToString())],now.AddMinutes(-10),now.AddMinutes(-5),new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(SigningKey)),SecurityAlgorithms.HmacSha256));var raw=new JwtSecurityTokenHandler().WriteToken(token);Assert.Throws<SecurityTokenExpiredException>(()=>new JwtSecurityTokenHandler().ValidateToken(raw,ValidationParameters(),out _));}
private static IConfiguration Configuration()=>new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Jwt:Key",SigningKey},{"Jwt:Issuer","test"},{"Jwt:Audience","test-app"}}).Build();private static async Task<AuthTokenPair>IssueAsync()=>await new JwtTokenService(Configuration(),new FakeDb(),new EmptyPermissions()).IssueAsync(Guid.NewGuid(),"user@example.com",["Customer"],"device","agent","127.0.0.1");private static TokenValidationParameters ValidationParameters()=>new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer="test",ValidAudience="test-app",IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(SigningKey)),ClockSkew=TimeSpan.Zero};
 private sealed class EmptyPermissions:IPermissionResolver{public Task<IReadOnlyCollection<string>>ForRolesAsync(IEnumerable<string>roleNames,CancellationToken ct=default)=>Task.FromResult<IReadOnlyCollection<string>>([]);}private sealed class FakeDb:IApplicationDbContext{private readonly List<UserSession>sessions=[];public List<object>Added{get;}=[];public IQueryable<Category>Categories=>Array.Empty<Category>().AsQueryable();public IQueryable<Product>Products=>Array.Empty<Product>().AsQueryable();public IQueryable<ProductVariant>ProductVariants=>Array.Empty<ProductVariant>().AsQueryable();public IQueryable<Inventory>Inventories=>Array.Empty<Inventory>().AsQueryable();public IQueryable<Cart>Carts=>Array.Empty<Cart>().AsQueryable();public IQueryable<Address>Addresses=>Array.Empty<Address>().AsQueryable();public IQueryable<Order>Orders=>Array.Empty<Order>().AsQueryable();public IQueryable<Coupon>Coupons=>Array.Empty<Coupon>().AsQueryable();public IQueryable<StockMovement>StockMovements=>Array.Empty<StockMovement>().AsQueryable();public IQueryable<UserSession>UserSessions=>sessions.AsQueryable();public IQueryable<RefreshToken>RefreshTokens=>Added.OfType<RefreshToken>().AsQueryable();public IQueryable<SecurityEvent>SecurityEvents=>Array.Empty<SecurityEvent>().AsQueryable();public IQueryable<AuditLog>AuditLogs=>Array.Empty<AuditLog>().AsQueryable();public void Add<T>(T entity)where T:class{Added.Add(entity);if(entity is UserSession s)sessions.Add(s);}public void Remove<T>(T entity)where T:class=>Added.Remove(entity);public Task<int>SaveChangesAsync(CancellationToken cancellationToken=default)=>Task.FromResult(1);}}
